package com.aicharacter.v3;
/** Quadruped gait is mechanically coupled; player intent never moves four independent legs. */
public final class CatWholeBodyMotorEngine{private CatWholeBodyMotorEngine(){}
 public static void advance(WorldState s,double dt){if(s==null||dt<=0)return;if(s.catRig==null)s.catRig=new CatRigState();CatRigState r=s.catRig;PhysicsBodyState p=s.catPhysics;double speed=s.catTravel!=null&&s.catTravel.active?s.catTravel.lastSpeed:0,gait=Math.max(0,Math.min(1,speed/105.0));double total=s.catTravel==null?0:Math.max(0,s.catTravel.distanceTravelled);if(total+1e-6<r.lastDistanceSample)r.lastDistanceSample=0;double travelled=Math.max(0,total-r.lastDistanceSample);r.lastDistanceSample=total;double stridePx=WorldUnits.mToPx(.42);r.gaitPhase=(r.gaitPhase+travelled/Math.max(1,stridePx))%1;double w=Math.sin(r.gaitPhase*Math.PI*2),q=Math.sin((r.gaitPhase+.5)*Math.PI*2);if(gait<.06){r.frontLeftContact=r.frontRightContact=r.hindLeftContact=r.hindRightContact=1;}else{r.frontLeftContact=w>=-.1?1:0;r.hindRightContact=r.frontLeftContact;r.frontRightContact=q>=-.1?1:0;r.hindLeftContact=r.frontRightContact;}r.frontLoad=Math.max(.28,Math.min(.72,.52-w*.10*gait));r.hindLoad=1-r.frontLoad;r.spineFlex=w*.08*gait;r.trunkLean=(1-(p==null?1:p.balance))*.10;double gx=s.catState==null?s.catX:s.catState.x,front=WorldUnits.mToPx(.20),hind=WorldUnits.mToPx(.18),swing=WorldUnits.mToPx(.12)*w*gait;if(!Double.isFinite(r.frontLeftWorldX))r.frontLeftWorldX=gx+front;if(!Double.isFinite(r.frontRightWorldX))r.frontRightWorldX=gx+front;if(!Double.isFinite(r.hindLeftWorldX))r.hindLeftWorldX=gx-hind;if(!Double.isFinite(r.hindRightWorldX))r.hindRightWorldX=gx-hind;if(r.frontLeftContact<.5)r.frontLeftWorldX=gx+front+swing;if(r.frontRightContact<.5)r.frontRightWorldX=gx+front-swing;if(r.hindLeftContact<.5)r.hindLeftWorldX=gx-hind-swing;if(r.hindRightContact<.5)r.hindRightWorldX=gx-hind+swing;if(p!=null){double min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY,pawHalf=.045;double[]xs={r.frontLeftWorldX,r.frontRightWorldX,r.hindLeftWorldX,r.hindRightWorldX},cs={r.frontLeftContact,r.frontRightContact,r.hindLeftContact,r.hindRightContact};for(int i=0;i<4;i++)if(cs[i]>.5){double local=WorldUnits.pxToM(xs[i]-gx);min=Math.min(min,local-pawHalf);max=Math.max(max,local+pawHalf);}if(min==Double.POSITIVE_INFINITY){p.supportLeft=-.02;p.supportRight=.02;}else{p.supportLeft=min;p.supportRight=max;}double supportCenter=(p.supportLeft+p.supportRight)*.5;p.centerOfMassX=supportCenter+r.trunkLean*.10+w*.025*gait;}}
}
